BOOL __fastcall Skills_SrvDoFunc_036_ChargeRelease_MissileRing(::SGAMEDATA * pGame, D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    D2UnitStrc* pTarget = UNIT::SUnit::GetTargetEx(pGame, pUnit);
    if (!pTarget) {
      return 0;
    }
    if (nSkillLvl <= 0) {
      return 0;
    }
    if (!((int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount)) {
      return 0;
    }

    D2SkillsTxt* pSkillTxtBase = sgptDataTable->pTxtSkills;
    if (!(pSkillTxtBase + eSkill)) {
      return 0;
    }

    eMissilesId nMissileId = SKILLASS_GetChargeUpMissile(pUnit, eSkill);
    if ((int)nMissileId <= 0) {
      return 0;
    }

    int32_t nVelocity = D2Common::DATATBLS::MissileTbls::MISSILETBLS_CalculateVelocity(nMissileId, nSkillLvl);
    int32_t nCalcBonus = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillTxtBase[eSkill].calc[0], eSkill, nSkillLvl);
    SkillsServer::SKILLS_CreateMissileRing(pGame, pUnit, pTarget, nMissileId, eSkill, nSkillLvl, nVelocity + nCalcBonus);
    return 1;
}

BOOL __fastcall Skills_SrvDoFunc_037_ChargeRelease_MultiElementScatter(::SGAMEDATA * pGame, D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    uint32_t nTargetX;
    eD2Skills eSkillSaved = eSkill;
    D2SeedStrc DVar1 = D2_SEED_NEXT(pUnit->sSeed);
    pUnit->sSeed.nSeedHigh = DVar1.nSeedHigh;
    pUnit->sSeed.nSeedLow = DVar1.nSeedLow;
    if (!((int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount)) {
      return 0;
    }

    D2SkillsTxt* pSkillTxt = sgptDataTable->pTxtSkills + eSkill;
    if (!pSkillTxt) {
      return 0;
    }

    ::SGAMEDATA* pGameCopy = pGame;
    uint32_t nChargeUpMissileId = SKILLASS_GetChargeUpMissile(pUnit, eSkill);
    if ((int)nChargeUpMissileId <= 0) {
      return 0;
    }

    BOOL bHasPos = SkillsServer::SKILLS_GetTargetOrCursorPos(pGameCopy, pUnit, &nTargetX, &eSkill);
    if (!bHasPos) {
      return 0;
    }

    uint32_t nScatterRadius = SKILLASS_GetChargeUpCalcValue(pUnit, eSkillSaved, nSkillLvl);
    if (!nScatterRadius) {
      nScatterRadius = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillTxt->aurarangecalc, eSkillSaved, nSkillLvl);
    }

    SKILLASS_SpawnMissileRing(nChargeUpMissileId, (D2UnitStrc*)DVar1.nSeedLow, pGameCopy, pUnit, nChargeUpMissileId, nTargetX, eSkill, eSkillSaved, nSkillLvl, nScatterRadius);
    return 1;
}

